<script>
  import { onMount } from 'svelte';
  import Panel from '$lib/components/Panel.svelte';
  import PageHero from '$lib/components/PageHero.svelte';
  import StatusBanner from '$lib/components/StatusBanner.svelte';
  import { selectedModelId } from '$lib/stores/selection.js';
  import { fetchJson } from '$lib/api/client.js';
  import { loadAdminUiConfig } from '$lib/api/ui.js';
  import { initAuthStores } from '$lib/stores/auth.js';
  import { centralTargets, centralCapabilities, centralBindings, centralContext, centralPreview, centralSubmit, centralJobs, centralReview, centralDecide, centralOutcome, centralDeliveries, centralInspectDelivery, centralResolveDelivery } from '$lib/api/central-edits.js';
  let models = [], targets = [], target = '', bindings = [], bindingCursor = '', element = '', context = null, field = '', value = '', clear = false;
  let jobs = [], jobCursor = '', deliveries = [], deliveryCursor = '', capabilities = {}, reviewed = null, resolveDrift = false, inspection = null;
  let preview = null, previewSignature = '', pending = null, confirmed = false, busy = false, sequence = 0;
  let message = 'Choose a model and an approved central-edit target.';
  $: selectedField = context?.fields.find(item => item.field === field);
  $: proposed = field ? { [field]: clear ? null : value } : {};
  $: signature = JSON.stringify([$selectedModelId, target, element, proposed]);
  $: if (previewSignature !== signature) { preview = null; confirmed = false; }
  const work = async action => { if (busy) return; busy = true; try { await action(); } catch (error) { message = error.message; } finally { busy = false; } };
  const loadJobs = async (more = false) => { if (!capabilities.canRequest && !capabilities.canApprove) { jobs = []; return; } const model = $selectedModelId, key = target; const result = await centralJobs(model, key, more ? jobCursor : ''); if (model !== $selectedModelId || key !== target) return; jobs = more ? [...jobs, ...result.jobs] : result.jobs; jobCursor = result.nextCursor || ''; };
  const loadDeliveries = async (more = false) => { if (!capabilities.canResolve) return; const model = $selectedModelId, key = target; const rows = await centralDeliveries(model, key, more ? deliveryCursor : ''); if (model !== $selectedModelId || key !== target) return; deliveries = more ? [...deliveries, ...rows] : rows; deliveryCursor = rows.length === 100 ? rows[rows.length - 1].id : ''; };
  const loadElement = async () => { context = null; preview = null; confirmed = false; if (!element) return; const model = $selectedModelId, key = target, chosen = element; const result = await centralContext(model, key, chosen); if (model !== $selectedModelId || key !== target || chosen !== element) return; context = result; field = result.fields[0]?.field || ''; value = ''; clear = false; };
  const loadBindings = async (more = false) => { const result = await centralBindings($selectedModelId, target, more ? bindingCursor : ''); bindings = more ? [...bindings, ...result.items] : result.items; bindingCursor = result.nextCursor || ''; if (!more) { element = bindings[0]?.elementId || ''; await loadElement(); } };
  const loadTarget = async () => { context = null; preview = null; reviewed = null; inspection = null; pending = null; jobs = []; deliveries = []; capabilities = {}; if (!target) return; capabilities = await centralCapabilities($selectedModelId, target); if (capabilities.canRequest || capabilities.canApprove) await loadBindings(); await loadJobs(); await loadDeliveries(); };
  const loadModel = async () => { const current = ++sequence, model = $selectedModelId; target = ''; targets = []; context = null; jobs = []; deliveries = []; reviewed = null; inspection = null; preview = null; pending = null; if (!model) return; const available = await centralTargets(model); if (current !== sequence || model !== $selectedModelId) return; targets = available; target = targets[0] || ''; if (target) await loadTarget(); else message = 'No central edit scope is enabled for this model and user.'; };
  const makePreview = () => work(async () => { const before = signature; const result = await centralPreview($selectedModelId, target, { ref: 'HEAD', elementId: element, proposed }); if (before !== signature) return; previewSignature = before; preview = result; confirmed = false; message = result.mode === 'PROPOSAL' ? 'This request requires approval. No central write occurs before a scoped administrator approves it.' : 'This explicitly permitted write-through will update the central card and then reconcile model occurrences.'; });
  const submit = () => work(async () => { if (!preview || !confirmed) return; pending ||= { requestId: crypto.randomUUID(), ref: 'HEAD', elementId: element, proposed, previewDigest: preview.digest }; const result = await centralSubmit($selectedModelId, target, pending); pending = null; preview = null; confirmed = false; await loadJobs(); message = `Request ${result.state}. Remote verification and model delivery are tracked separately.`; });
  const review = job => work(async () => { reviewed = await centralReview($selectedModelId, target, job.id); resolveDrift = false; });
  const decide = approve => work(async () => { await centralDecide($selectedModelId, target, reviewed.id, { expectedVersion: reviewed.version, approve, reviewDigest: reviewed.digest, resolveDrift }); reviewed = null; await loadJobs(); message = approve ? 'Proposal approved and queued. Inspect remote verification and delivery status.' : 'Proposal rejected without a remote write.'; });
  const outcome = (job, action) => work(async () => { const result = await centralOutcome($selectedModelId, target, job.id, action, job.version); await loadJobs(); await loadDeliveries(); message = `Request ${result.state}${result.code ? `: ${result.code}` : ''}.`; });
  const inspectDelivery = row => work(async () => { const result = await centralInspectDelivery($selectedModelId, target, row.jobId, row.elementId); inspection = { ...result, jobId: row.jobId }; });
  const resolveDelivery = () => work(async () => { await centralResolveDelivery($selectedModelId, target, inspection.jobId, inspection.elementId, inspection.digest); inspection = null; await loadJobs(); await loadDeliveries(); message = 'Approved central values verified in this model through ordinary accepted operations.'; });
  const show = value => value === null || value === undefined ? '(not set)' : String(value);
  onMount(() => {
    work(async () => { initAuthStores(); selectedModelId.init(); await loadAdminUiConfig(); models = await fetchJson('/models', { action: 'Readable models' }); if (!$selectedModelId && models.length) selectedModelId.set(models[0].modelId); await loadModel(); });
    const timer = setInterval(() => { if (!busy && target && !pending && jobs.length <= 50 && deliveries.length <= 100) work(async () => { await loadJobs(); await loadDeliveries(); }); }, 5000);
    return () => clearInterval(timer);
  });
</script>
<PageHero eyebrow="Central changes" title="Review an explicit central change before it is written." description="Proposals require approval. Write-through is limited to explicitly permitted fields. Ordinary model editing does not grant central write authority." />
<StatusBanner message={message} />
<Panel title="Model and target" subtitle="Requester and approver scopes are separate and also require current model access.">
  <div class="controls"><label>Model <select value={$selectedModelId} disabled={busy || !!pending} on:change={event => { selectedModelId.set(event.currentTarget.value); work(loadModel); }}><option value="">Choose model</option>{#each models as model}<option value={model.modelId}>{model.modelName || model.modelId}</option>{/each}</select></label><label>Target <select bind:value={target} disabled={busy || !!pending} on:change={() => work(loadTarget)}>{#each targets as key}<option value={key}>{key}</option>{/each}</select></label><button class="secondary" disabled={busy || !target} on:click={() => work(async () => { await loadJobs(); await loadDeliveries(); })}>Refresh status</button></div>
</Panel>
{#if target}
  {#if capabilities.canRequest}<Panel title="Request a central change" subtitle="Only selected mapped fields are sent. Use JSON text for numeric, boolean, object and multiselect values; precision is preserved.">
    <div class="controls"><label>Linked element <select bind:value={element} disabled={busy || !!pending} on:change={() => work(loadElement)}>{#each bindings as binding}<option value={binding.elementId}>{binding.name || binding.elementId}</option>{/each}</select></label>{#if bindingCursor}<button class="secondary" disabled={busy || !!pending} on:click={() => work(() => loadBindings(true))}>More elements</button>{/if}<label>Field <select bind:value={field} disabled={busy || !!pending} on:change={() => { value = ''; clear = false; }}>{#each context?.fields || [] as item}<option value={item.field}>{item.field} · {item.authority} · {item.mode}</option>{/each}</select></label></div>
    {#if context}<p>{context.canonicalId} · card {context.resourceId} · {context.type}</p>{/if}
    {#if selectedField}<div class="comparison"><div><strong>Last agreed baseline</strong><pre>{show(selectedField.baseline)}</pre></div><div><strong>Current model value</strong><pre>{show(selectedField.local)}</pre></div><div><strong>Current central value</strong><pre>{selectedField.currentText}</pre></div></div>
      <label class="value">Proposed {selectedField.valueType === 'STRING' ? 'text' : `${selectedField.valueType.toLowerCase()} as JSON text`} <textarea bind:value={value} maxlength="16384" disabled={busy || !!pending || clear} rows="3"></textarea></label><label><input type="checkbox" bind:checked={clear} disabled={busy || !!pending || selectedField.remoteField === 'name'} /> Remove/clear this value</label>
      <button disabled={busy || !!pending} on:click={makePreview}>Preview central change</button>
    {/if}
    {#if preview}<p><strong>{preview.mode}</strong> · proposed values:</p>{#each Object.entries(preview.proposedText) as [key, text]}<pre>{key}: {text}</pre>{/each}{#if preview.driftFields.length}<p>Baseline review required: {preview.driftFields.join(', ')}</p>{/if}<label><input type="checkbox" bind:checked={confirmed} disabled={busy || !!pending} /> I confirm this explicit request for the shown central resource and values.</label><button disabled={busy || !confirmed} on:click={submit}>{pending ? 'Retry same request' : preview.mode === 'PROPOSAL' ? 'Submit proposal' : 'Apply central change'}</button>{/if}
  </Panel>{/if}
  {#if capabilities.canRequest || capabilities.canApprove}<Panel title="Requests and delivery" subtitle="Remote verification does not imply every linked model is synchronized. Ambiguous writes require read-only outcome verification; their PATCH is never blindly repeated.">
    <div class="table-wrap"><table><thead><tr><th>Element/requester</th><th>State</th><th>Remote verified</th><th>Model deliveries</th><th>Actions</th></tr></thead><tbody>{#each jobs as job}<tr><td>{job.elementId}<br /><small>{job.requestedBy}</small>{#each Object.entries(job.proposedText) as [key, text]}<pre>{key}: {text}</pre>{/each}</td><td>{job.state}<br /><small>{job.code || ''}</small></td><td>{job.remoteVerified ? 'Yes' : 'Pending'}</td><td>{job.synced} synced · {job.pending} pending · {job.conflicts} conflicts<br /><small>This model: {job.sourceState || 'pending'}</small></td><td>{#if job.state === 'WAITING_APPROVAL' && capabilities.canApprove}<button disabled={busy} on:click={() => review(job)}>Review proposal</button>{/if}{#if job.state === 'AMBIGUOUS'}<button class="secondary" disabled={busy} on:click={() => outcome(job, 'verify-outcome')}>Verify remote outcome</button>{/if}{#if job.remoteVerified && ['PARTIAL', 'SYNCED', 'ERROR', 'CONFLICT'].includes(job.state)}<button class="secondary" disabled={busy} on:click={() => outcome(job, 'retry-fanout')}>Retry model delivery</button>{/if}{#if !job.remoteVerified && ['PENDING', 'WAITING_APPROVAL', 'RETRY', 'PAUSED'].includes(job.state) && capabilities.canRequest}<button class="secondary" disabled={busy} on:click={() => outcome(job, 'cancel')}>Cancel own request</button>{/if}</td></tr>{/each}</tbody></table></div>
    {#if jobCursor}<button class="secondary" disabled={busy} on:click={() => work(() => loadJobs(true))}>More requests</button>{/if}
  </Panel>{/if}
  {#if reviewed}<Panel title="Approve or reject this proposal" subtitle="Approval is bound to these current values and the reviewed model. A changed remote value requires a fresh proposal.">
    <p>{reviewed.preview.context.canonicalId} · card {reviewed.preview.context.resourceId}</p>{#each reviewed.preview.context.fields as item}<h3>{item.field} · {item.authority}</h3><div class="comparison"><div>Baseline<pre>{show(item.baseline)}</pre></div><div>Local<pre>{show(item.local)}</pre></div><div>Central<pre>{item.currentText}</pre></div></div><strong>Proposed</strong><pre>{reviewed.preview.proposedText[item.field]}</pre>{/each}
    {#if reviewed.baseChanged}<p>The proposal's original local or remote values changed. Refresh the request context and submit a new proposal.</p>{/if}
    {#if reviewed.preview.driftFields.length}<label><input type="checkbox" bind:checked={resolveDrift} disabled={busy} /> I approve this baseline resolution for {reviewed.preview.driftFields.join(', ')}.</label>{/if}
    <div class="controls"><button disabled={busy || reviewed.baseChanged || reviewed.preview.driftFields.length > 0 && !resolveDrift} on:click={() => decide(true)}>Approve central change</button><button class="secondary" disabled={busy} on:click={() => decide(false)}>Reject proposal</button></div>
  </Panel>{/if}
  {#if capabilities.canResolve}<Panel title="Incoming approved changes for this model" subtitle="A local conflict can be resolved by this model's authorized inbound administrator, after reviewing the approved central values.">
    {#each deliveries as row}<div class="delivery"><span>{row.elementId} · {row.state} · {row.code || ''}</span>{#if row.state !== 'SYNCED'}<button class="secondary" disabled={busy} on:click={() => inspectDelivery(row)}>Inspect this delivery</button>{/if}</div>{/each}{#if deliveryCursor}<button class="secondary" disabled={busy} on:click={() => work(() => loadDeliveries(true))}>More deliveries</button>{/if}
    {#if inspection}<p>{inspection.elementId} · HEAD revision {inspection.revision}</p><div class="comparison"><div>Baseline<pre>{JSON.stringify(inspection.base, null, 2)}</pre></div><div>Local<pre>{JSON.stringify(inspection.local, null, 2)}</pre></div><div>Approved central values<pre>{JSON.stringify(inspection.remote, null, 2)}</pre></div></div><button disabled={busy} on:click={resolveDelivery}>Accept these approved values into this model</button>{/if}
  </Panel>{/if}
{/if}
<style>
  .controls { display:flex; flex-wrap:wrap; gap:1rem; align-items:end; margin:1rem 0; } .controls label,.value { display:grid; gap:0.4rem; }
  .comparison { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:1rem; margin:1rem 0; }
  textarea { width:100%; } pre { white-space:pre-wrap; overflow-wrap:anywhere; margin:0.5rem 0; } small { color:var(--text-muted); }
  .table-wrap { overflow-x:auto; } table { width:100%; border-collapse:collapse; } th,td { padding:0.75rem; border-bottom:1px solid var(--line); text-align:left; vertical-align:top; }
  label { margin:0.6rem 0; } button { margin-right:0.4rem; } .delivery { display:flex; flex-wrap:wrap; gap:1rem; align-items:center; padding:0.5rem 0; }
  @media(max-width:900px) { .comparison { grid-template-columns:1fr; } }
</style>
